<template>
  <div class="page-head">
    <div><h2>多源数据</h2><span class="muted">统一管理施工区域水害识别所需的环境数据</span></div>
    <n-space>
      <input ref="fileInput" hidden type="file" accept=".tif,.tiff" multiple @change="uploadFiles">
      <input ref="demFileInput" hidden type="file" accept=".tif,.tiff" @change="chooseDem">
      <input ref="rainCsvInput" hidden type="file" accept=".csv" @change="importRainCsv">
      <input ref="uavFileInput" hidden type="file" accept=".tif,.tiff" @change="chooseUav">
      <n-button :loading="uploading" @click="fileInput?.click()">批量上传</n-button>
      <n-button :loading="demUploading" @click="demFileInput?.click()">导入DEM</n-button>
      <n-button :loading="uavUploading" @click="uavFileInput?.click()">导入无人机正射影像</n-button>
      <n-button type="primary" :loading="batchRunning" :disabled="!checked.length || batchRunning" @click="batchInference">批量识别（{{ checked.length }}）</n-button>
    </n-space>
  </div>
  <n-alert class="tech-alert" type="info" :bordered="false" style="margin-bottom:16px">
    已接入 Sentinel-1 SAR、DEM 数字高程、人工/CSV 降雨观测及无人机正射影像，并保留真实来源与质量状态。无人机数据仅用于正射影像管理、空间覆盖分析和人工协同复核，不包含自动积水识别、实时视频或飞控能力。
  </n-alert>
  <n-card title="无人机正射影像" class="data-table-panel" style="margin-bottom:16px">
    <template #header-extra><n-space><n-button tag="a" :href="api.uavCsvUrl()" download>导出清单CSV</n-button><n-button tag="a" :href="api.uavCoverageCsvUrl()" download>导出覆盖CSV</n-button></n-space></template>
    <n-data-table v-if="loading||uavRows.length" :loading="loading" :columns="uavColumns" :data="uavRows" :pagination="{pageSize:6}" :scroll-x="1450"/>
    <div v-else class="empty-table-panel"><h4>暂无无人机正射影像</h4><p>可按项目导入具备空间参考的 GeoTIFF 正射影像。</p><n-button @click="uavFileInput?.click()">导入无人机正射影像</n-button></div>
    <p class="muted">仅接收具备CRS、有效Transform与Bounds的RGB/RGBA GeoTIFF；像素尺寸不自动等同于已验证GSD精度。</p>
  </n-card>
  <n-card title="降雨观测与事件" class="data-table-panel rainfall-panel" style="margin-bottom:16px">
    <div class="rain-toolbar"><n-select v-model:value="rainProjectId" :options="projectOptions" placeholder="选择施工项目" @update:value="loadRain"/><n-button :disabled="!rainProjectId" @click="openStation()">新增雨量站</n-button><n-button :disabled="!rainProjectId||!rainStations.length" @click="observationVisible=true">录入观测</n-button><n-button :disabled="!rainProjectId" @click="rainCsvInput?.click()">导入CSV</n-button><n-button type="primary" :disabled="!rainProjectId" :loading="rainGenerating" @click="generateEvents">生成事件</n-button></div>
    <n-alert v-if="rainProjectId&&!rainOverview?.has_data" type="info" style="margin:12px 0">暂无降雨观测数据；这不表示项目近期没有降雨。</n-alert>
    <n-descriptions v-if="rainOverview?.has_data" bordered :column="5" size="small" style="margin:12px 0"><n-descriptions-item label="雨量站">{{rainOverview.station_count}}</n-descriptions-item><n-descriptions-item label="最近24小时">{{rainValue(rainOverview.rainfall_24h_mm)}}</n-descriptions-item><n-descriptions-item label="最近72小时">{{rainValue(rainOverview.rainfall_72h_mm)}}</n-descriptions-item><n-descriptions-item label="最近7天">{{rainValue(rainOverview.rainfall_7d_mm)}}</n-descriptions-item><n-descriptions-item label="最近观测">{{formatDateTime(rainOverview.latest_observation_at)}}</n-descriptions-item></n-descriptions>
    <n-tabs type="line"><n-tab-pane name="stations" tab="雨量站"><n-space justify="end" style="margin-bottom:8px"><n-button tag="a" :href="api.stationsCsvUrl(rainProjectId||undefined)" download>导出CSV</n-button></n-space><n-data-table :columns="stationColumns" :data="rainStations" :pagination="{pageSize:5}"/></n-tab-pane><n-tab-pane name="observations" tab="观测记录"><n-space justify="end" style="margin-bottom:8px"><n-button tag="a" :href="api.observationsCsvUrl(rainProjectId||undefined)" download>导出CSV</n-button></n-space><n-data-table :columns="observationColumns" :data="rainObservations" :pagination="{pageSize:8}"/></n-tab-pane><n-tab-pane name="events" tab="降雨事件"><n-space justify="end" style="margin-bottom:8px"><n-button tag="a" :href="api.eventsCsvUrl(rainProjectId||undefined)" download>导出CSV</n-button></n-space><n-data-table :columns="eventColumns" :data="rainEvents" :pagination="{pageSize:6}"/></n-tab-pane></n-tabs>
    <p class="muted">降雨事件用于组织历史观测，不是气象风险等级；“自动雨量站”仅表示来源类型，不表示实时在线。</p>
  </n-card>
  <n-card title="DEM数字高程数据" class="data-table-panel" style="margin-bottom:16px">
    <n-data-table v-if="loading||demRows.length" :loading="loading" :columns="demColumns" :data="demRows" :pagination="{pageSize:8}" :scroll-x="1200"/>
    <div v-else class="empty-table-panel"><h4>暂无 DEM 数字高程数据</h4><p>导入具有明确空间参考的单波段 GeoTIFF 后，可生成地形辅助分析。</p><n-button @click="demFileInput?.click()">导入 DEM</n-button></div>
  </n-card>
  <n-card title="Sentinel-1 SAR环境数据" class="data-table-panel">
    <n-data-table v-model:checked-row-keys="checked" :row-key="rowKey" :loading="loading" :columns="columns" :data="rows" :pagination="{pageSize:10}"/>
  </n-card>
  <n-drawer v-model:show="detailShow" :width="780" :title="selected?.filename||'遥感影像详细元数据'">
    <n-drawer-content closable>
      <n-spin :show="detailLoading">
        <template v-if="detail">
          <n-divider title-placement="left" style="margin-top:0">基础信息</n-divider>
          <n-descriptions bordered :column="2" label-placement="left" size="small">
            <n-descriptions-item label="数据名称">{{detail.filename}}</n-descriptions-item>
            <n-descriptions-item label="数据状态"><n-tag type="success" size="small">有效</n-tag></n-descriptions-item>
            <n-descriptions-item label="文件哈希 SHA256" :span="2">{{detail.file_hash||'--'}}</n-descriptions-item>
            <n-descriptions-item label="影像宽度">{{detail.width}}</n-descriptions-item>
            <n-descriptions-item label="影像高度">{{detail.height}}</n-descriptions-item>
            <n-descriptions-item label="波段数">{{detail.bands}}</n-descriptions-item>
            <n-descriptions-item label="数据类型">{{detail.dtype}}</n-descriptions-item>
            <n-descriptions-item label="数据来源">{{detail.source_type||'--'}}</n-descriptions-item>
            <n-descriptions-item label="导入时间">{{formatDateTime(detail.created_at)}}</n-descriptions-item>
            <n-descriptions-item label="影像采集时间" :span="2"><n-space><span>{{detail.capture_time?formatDateTime(detail.capture_time):'未填写（降雨关联将标记时间参考受限）'}}</span><n-input v-model:value="captureTimeInput" size="small" placeholder="ISO时间，如 2026-10-13T08:00:00+08:00" style="width:290px"/><n-button size="small" @click="saveCaptureTime">保存</n-button></n-space></n-descriptions-item>
          </n-descriptions>
          <n-divider title-placement="left">空间信息</n-divider>
          <n-descriptions bordered :column="2" label-placement="left" size="small">
            <n-descriptions-item label="CRS">{{detail.crs||'未定义'}}</n-descriptions-item>
            <n-descriptions-item label="NoData">{{detail.nodata||'无'}}</n-descriptions-item>
            <n-descriptions-item label="Bounds" :span="2">{{fmtBounds(detail.bounds)}}</n-descriptions-item>
            <n-descriptions-item label="Transform" :span="2">{{fmtTransform(detail.transform)}}</n-descriptions-item>
          </n-descriptions>
          <n-divider title-placement="left">波段统计（仅有效像素）</n-divider>
          <n-descriptions bordered :column="2" label-placement="left" size="small">
            <n-descriptions-item label="VV 最小值">{{bandStat(detail.vv_stats,'min')}}</n-descriptions-item>
            <n-descriptions-item label="VV 最大值">{{bandStat(detail.vv_stats,'max')}}</n-descriptions-item>
            <n-descriptions-item label="VV 均值">{{bandStat(detail.vv_stats,'mean')}}</n-descriptions-item>
            <n-descriptions-item label="VV NaN 数量">{{bandStat(detail.vv_stats,'nan_count')}}</n-descriptions-item>
            <n-descriptions-item label="VV Inf 数量">{{bandStat(detail.vv_stats,'inf_count')}}</n-descriptions-item>
            <n-descriptions-item label="VH 最小值">{{bandStat(detail.vh_stats,'min')}}</n-descriptions-item>
            <n-descriptions-item label="VH 最大值">{{bandStat(detail.vh_stats,'max')}}</n-descriptions-item>
            <n-descriptions-item label="VH 均值">{{bandStat(detail.vh_stats,'mean')}}</n-descriptions-item>
            <n-descriptions-item label="VH NaN 数量">{{bandStat(detail.vh_stats,'nan_count')}}</n-descriptions-item>
            <n-descriptions-item label="VH Inf 数量">{{bandStat(detail.vh_stats,'inf_count')}}</n-descriptions-item>
          </n-descriptions>
          <n-divider title-placement="left">历史识别</n-divider>
          <n-descriptions bordered :column="2" label-placement="left" size="small">
            <n-descriptions-item label="历史识别次数">{{detail.history?.inference_count??0}}</n-descriptions-item>
            <n-descriptions-item label="最近一次识别时间">{{detail.history?.last_inference_at?formatDateTime(detail.history.last_inference_at):'--'}}</n-descriptions-item>
            <n-descriptions-item label="最近一次积水占比">{{detail.history?.last_flood_ratio!=null?`${(detail.history.last_flood_ratio*100).toFixed(2)}%`:'--'}}</n-descriptions-item>
            <n-descriptions-item label="最近基础水害提示">{{detail.history?.last_risk_level||'--'}}</n-descriptions-item>
          </n-descriptions>
        </template>
      </n-spin>
    </n-drawer-content>
  </n-drawer>
  <n-modal v-model:show="showBatch" preset="card" title="批量上传结果" style="width:720px">
    <template v-if="batchResult">
      <div class="count-summary"><span>总数 <b>{{batchResult.total}}</b></span><span>成功 <b>{{batchResult.success_count}}</b></span><span>重复 <b>{{batchResult.duplicate_count}}</b></span><span>失败 <b>{{batchResult.failed_count}}</b></span></div>
      <n-data-table :columns="batchColumns" :data="batchResult.items" :pagination="{pageSize:8}"/>
    </template>
  </n-modal>
  <n-modal v-model:show="demUploadVisible" preset="card" title="导入DEM数字高程数据" style="width:680px"><n-alert type="info" style="margin-bottom:14px">正式支持具有明确CRS的单波段GeoTIFF。来源、采集日期和垂向基准不会自动推测。</n-alert><div class="dem-form"><n-select v-model:value="demForm.project_id" :options="projectOptions" clearable placeholder="关联施工项目（可选）"/><n-input v-model:value="demForm.source_name" placeholder="DEM来源（可选）"/><n-input v-model:value="demForm.capture_date" placeholder="采集日期（可选）"/><n-input v-model:value="demForm.resolution_note" placeholder="分辨率说明（可选）"/><n-input v-model:value="demForm.vertical_datum_note" placeholder="垂向基准说明（可选）"/><n-input v-model:value="demForm.description" placeholder="说明（可选）"/></div><n-space justify="end"><n-button @click="demUploadVisible=false">取消</n-button><n-button type="primary" :loading="demUploading" @click="uploadDem">校验并导入</n-button></n-space></n-modal>
  <n-modal v-model:show="demDetailVisible" preset="card" style="width:min(900px,92vw)" title="DEM详情"><template v-if="demDetail"><n-descriptions bordered :column="3"><n-descriptions-item label="名称">{{demDetail.name}}</n-descriptions-item><n-descriptions-item label="CRS">{{demDetail.crs}}</n-descriptions-item><n-descriptions-item label="尺寸">{{demDetail.width}} × {{demDetail.height}}</n-descriptions-item><n-descriptions-item label="最低高程">{{demDetail.min_elevation.toFixed(2)}} m</n-descriptions-item><n-descriptions-item label="最高高程">{{demDetail.max_elevation.toFixed(2)}} m</n-descriptions-item><n-descriptions-item label="平均高程">{{demDetail.mean_elevation.toFixed(2)}} m</n-descriptions-item><n-descriptions-item label="标准差">{{demDetail.elevation_std.toFixed(2)}} m</n-descriptions-item><n-descriptions-item label="有效像素">{{demDetail.valid_pixel_count}}</n-descriptions-item><n-descriptions-item label="NoData比例">{{(demDetail.nodata_ratio*100).toFixed(2)}}%</n-descriptions-item><n-descriptions-item label="来源">{{demDetail.source_name||'未填写'}}</n-descriptions-item><n-descriptions-item label="采集日期">{{demDetail.capture_date||'未填写'}}</n-descriptions-item><n-descriptions-item label="规则版本">{{demDetail.terrain_rule_version}}</n-descriptions-item></n-descriptions><div class="terrain-images"><img v-if="demDetail.files.elevation_preview" :src="demDetail.files.elevation_preview"><img v-if="demDetail.files.slope_preview" :src="demDetail.files.slope_preview"><img v-if="demDetail.files.low_mask_preview" :src="demDetail.files.low_mask_preview"></div><n-alert type="warning">相对低高程只表示当前DEM覆盖范围内的相对地形位置，不表示必然积水。</n-alert></template></n-modal>
  <n-modal v-model:show="stationVisible" preset="card" title="雨量站" style="width:650px"><div class="dem-form"><n-input v-model:value="stationForm.station_code" :disabled="!!editingStation" placeholder="站点编号"/><n-input v-model:value="stationForm.station_name" placeholder="站点名称"/><n-select v-model:value="stationForm.station_type" :options="stationTypeOptions"/><n-input v-model:value="stationForm.source_name" placeholder="数据来源（不自动填写）"/><n-input-number v-model:value="stationForm.x" clearable placeholder="X/经度"/><n-input-number v-model:value="stationForm.y" clearable placeholder="Y/纬度"/><n-input v-model:value="stationForm.crs" placeholder="CRS，如 EPSG:4326"/><n-input v-model:value="stationForm.location_description" placeholder="位置说明（可选）"/></div><n-space justify="end"><n-button @click="stationVisible=false">取消</n-button><n-button type="primary" @click="saveStation">保存</n-button></n-space></n-modal>
  <n-modal v-model:show="observationVisible" preset="card" title="录入降雨观测" style="width:620px"><div class="dem-form"><n-select v-model:value="observationForm.station_id" :options="rainStations.map(x=>({label:x.station_name+' · '+x.station_code,value:x.id}))" placeholder="雨量站"/><n-input v-model:value="observationForm.observed_at" placeholder="观测时间，如 2026-10-13T08:00:00+08:00"/><n-input-number v-model:value="observationForm.rainfall_mm" :min="0" placeholder="时段降雨量 mm"/><n-input-number v-model:value="observationForm.interval_minutes" :min="1" placeholder="时间间隔 分钟"/><n-input v-model:value="observationForm.source_note" placeholder="来源说明（可选）"/></div><n-alert type="info" style="margin-bottom:12px">雨强为该时段平均值，不是瞬时雨强；0 mm是真实观测。</n-alert><n-space justify="end"><n-button @click="observationVisible=false">取消</n-button><n-button type="primary" @click="saveObservation">保存</n-button></n-space></n-modal>
  <n-modal v-model:show="rainImportVisible" preset="card" title="降雨CSV导入结果" style="width:680px"><div v-if="rainImportResult" class="count-summary"><span>总行数 <b>{{rainImportResult.total}}</b></span><span>成功 <b>{{rainImportResult.success_count}}</b></span><span>失败 <b>{{rainImportResult.failed_count}}</b></span></div><n-data-table v-if="rainImportResult" :columns="[{title:'行号',key:'line'},{title:'状态',key:'status'},{title:'原因',key:'reason'}]" :data="rainImportResult.items" style="margin-top:12px"/></n-modal>
  <n-modal v-model:show="uavUploadVisible" preset="card" title="导入无人机正射影像" style="width:700px"><n-alert type="info" style="margin-bottom:14px">当前仅支持带空间参考的RGB/RGBA GeoTIFF。采集时间、航飞信息和设备说明不会自动推测。</n-alert><div class="dem-form"><n-select v-model:value="uavForm.project_id" :options="projectOptions" placeholder="关联施工项目（必选）"/><n-input v-model:value="uavForm.capture_time" placeholder="采集时间（可选，ISO格式）"/><n-input v-model:value="uavForm.flight_name" placeholder="航飞名称（可选）"/><n-input v-model:value="uavForm.flight_batch" placeholder="飞行批次（可选）"/><n-input v-model:value="uavForm.source_name" placeholder="数据来源（可选）"/><n-input v-model:value="uavForm.device_note" placeholder="设备说明（可选）"/><n-input v-model:value="uavForm.resolution_note" placeholder="分辨率说明（可选）"/><n-input v-model:value="uavForm.source_note" placeholder="来源备注（可选）"/></div><n-space justify="end"><n-button @click="uavUploadVisible=false">取消</n-button><n-button type="primary" :disabled="!uavForm.project_id" :loading="uavUploading" @click="uploadUav">校验并导入</n-button></n-space></n-modal>
  <n-modal v-model:show="uavDetailVisible" preset="card" title="无人机正射影像详情" style="width:min(940px,94vw)"><template v-if="uavDetail"><n-descriptions bordered :column="3"><n-descriptions-item label="影像名称">{{uavDetail.name}}</n-descriptions-item><n-descriptions-item label="施工项目">{{uavDetail.project_name}}</n-descriptions-item><n-descriptions-item label="采集时间">{{uavDetail.capture_time?formatDateTime(uavDetail.capture_time):'采集时间未填写'}}</n-descriptions-item><n-descriptions-item label="航飞名称">{{uavDetail.flight_name||'未填写'}}</n-descriptions-item><n-descriptions-item label="飞行批次">{{uavDetail.flight_batch||'未填写'}}</n-descriptions-item><n-descriptions-item label="来源">{{uavDetail.source_name||'未填写'}}</n-descriptions-item><n-descriptions-item label="CRS">{{uavDetail.crs}}</n-descriptions-item><n-descriptions-item label="尺寸">{{uavDetail.width}} × {{uavDetail.height}} · {{uavDetail.band_count}}波段</n-descriptions-item><n-descriptions-item label="像素尺寸">{{uavDetail.pixel_size_x.toFixed(4)}} × {{uavDetail.pixel_size_y.toFixed(4)}}</n-descriptions-item><n-descriptions-item label="空间范围" :span="3">{{fmtBounds(uavDetail.bounds)}}</n-descriptions-item></n-descriptions><img v-if="uavDetail.preview_url" class="uav-preview" :src="uavDetail.preview_url"><n-alert type="warning">该影像用于局部精细查看与人工复核，不生成无人机AI水害等级，也不判断道路或设备可安全通行。</n-alert></template></n-modal>
</template>
<script setup lang="ts">
import{computed,h,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{NButton,NDrawer,NDrawerContent,NPopconfirm,NTag,useMessage}from'naive-ui';import{api}from'../api';import type{BatchUploadItem,BatchUploadResult,ConstructionProject,Dataset,RainfallEvent,RainfallObservation,RainfallOverview,RainfallStation,TerrainDataset,UavDataset}from'../types';import{formatDateTime}from'../utils/format';
const rows=ref<Dataset[]>([]),demRows=ref<TerrainDataset[]>([]),uavRows=ref<UavDataset[]>([]),projects=ref<ConstructionProject[]>([]),checked=ref<Array<string|number>>([]),loading=ref(false),uploading=ref(false),demUploading=ref(false),uavUploading=ref(false),batchRunning=ref(false),detailShow=ref(false),showBatch=ref(false),demUploadVisible=ref(false),demDetailVisible=ref(false),uavUploadVisible=ref(false),uavDetailVisible=ref(false),selected=ref<Dataset|null>(null),detail=ref<Dataset|null>(null),demDetail=ref<TerrainDataset|null>(null),uavDetail=ref<UavDataset|null>(null),detailLoading=ref(false),batchResult=ref<BatchUploadResult|null>(null),fileInput=ref<HTMLInputElement|null>(null),demFileInput=ref<HTMLInputElement|null>(null),uavFileInput=ref<HTMLInputElement|null>(null),pendingDem=ref<File|null>(null),pendingUav=ref<File|null>(null),captureTimeInput=ref(''),msg=useMessage(),router=useRouter();
const demForm=ref({project_id:null as string|null,source_name:'',capture_date:'',resolution_note:'',vertical_datum_note:'',description:''}),projectOptions=computed(()=>projects.value.map(x=>({label:x.project_name,value:x.id})))
const uavForm=ref({project_id:null as string|null,capture_time:'',flight_name:'',flight_batch:'',source_name:'',source_note:'',device_note:'',resolution_note:''})
const rainProjectId=ref<string|null>(null),rainStations=ref<RainfallStation[]>([]),rainObservations=ref<RainfallObservation[]>([]),rainEvents=ref<RainfallEvent[]>([]),rainOverview=ref<RainfallOverview|null>(null),rainGenerating=ref(false),stationVisible=ref(false),observationVisible=ref(false),rainImportVisible=ref(false),rainImportResult=ref<any>(null),rainCsvInput=ref<HTMLInputElement|null>(null),editingStation=ref<RainfallStation|null>(null)
const stationForm=ref({station_code:'',station_name:'',station_type:'manual_station',source_name:'',x:null as number|null,y:null as number|null,crs:'',location_description:''}),observationForm=ref({station_id:null as string|null,observed_at:'',rainfall_mm:0,interval_minutes:60,source_note:''}),stationTypeOptions=[{label:'人工观测点',value:'manual_station'},{label:'自动雨量站（来源类型）',value:'automatic_station'},{label:'外部数据源',value:'external_source'}]
const load=async()=>{loading.value=true;try{[rows.value,demRows.value,uavRows.value,projects.value]=await Promise.all([api.datasets(),api.demDatasets(),api.uavDatasets(),api.projects()])}catch(e:any){msg.error(e.message||'加载数据失败')}finally{loading.value=false}};onMounted(load);const rowKey=(r:Dataset)=>r.id;
const uploadFiles=async(event:Event)=>{const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';if(!files.length)return;if(files.length>50){msg.error('单次最多上传 50 个文件');return}uploading.value=true;try{batchResult.value=await api.uploadBatch(files);showBatch.value=true;await load()}catch(e:any){msg.error(e.message)}finally{uploading.value=false}};
// 此处只把勾选的数据带到识别配置页；用户确认阈值并点击开始后才创建任务。
const batchInference=async()=>{if(batchRunning.value||!checked.value.length)return;batchRunning.value=true;try{const datasetIds=checked.value.map(String);await router.push({path:'/inference',query:{datasets:datasetIds.join(',')}})}catch(e:any){msg.error(e.message)}finally{batchRunning.value=false}};
const range=(s:any)=>`${s.min?.toFixed(2)} ~ ${s.max?.toFixed(2)}（均值 ${s.mean?.toFixed(2)}）`;
const bandStat=(s:any,k:string)=>s&&s[k]!=null?Number(s[k]).toFixed(2):'--';
const fmtBounds=(b:number[]|undefined)=>b&&b.length?b.map(v=>v.toFixed(4)).join(', '):'--';
const fmtTransform=(t:number[]|undefined)=>t&&t.length?t.map(v=>v.toFixed(6)).join(', '):'--';
const openDetail=async(r:Dataset)=>{selected.value=r;detail.value=null;detailShow.value=true;detailLoading.value=true;try{detail.value=await api.dataset(r.id);captureTimeInput.value=detail.value.capture_time||''}catch(e:any){msg.error(e.message)}finally{detailLoading.value=false}};
const saveCaptureTime=async()=>{if(!detail.value)return;try{detail.value=await api.updateDatasetCaptureTime(detail.value.id,captureTimeInput.value.trim()||null);msg.success('影像采集时间已保存');await load()}catch(e:any){msg.error(e.message)}}
const remove=async(r:Dataset)=>{try{await api.removeDataset(r.id);msg.success('已删除');await load()}catch(e:any){msg.error(e.message)}};
const chooseDem=(event:Event)=>{const input=event.target as HTMLInputElement;pendingDem.value=input.files?.[0]||null;input.value='';if(pendingDem.value)demUploadVisible.value=true}
const uploadDem=async()=>{if(!pendingDem.value)return;demUploading.value=true;try{const meta=Object.fromEntries(Object.entries(demForm.value).map(([k,v])=>[k,v||''])) as Record<string,string>;await api.uploadDem(pendingDem.value,meta);demUploadVisible.value=false;pendingDem.value=null;msg.success('DEM导入成功');await load()}catch(e:any){msg.error(e.message)}finally{demUploading.value=false}}
const deriveDem=async(r:TerrainDataset)=>{try{await api.deriveDem(r.id);msg.success('地形衍生成果已生成或复用');await load()}catch(e:any){msg.error(e.message)}}
const openDem=async(r:TerrainDataset)=>{try{demDetail.value=await api.demDataset(r.id);demDetailVisible.value=true}catch(e:any){msg.error(e.message)}}
const removeDem=async(r:TerrainDataset)=>{try{await api.removeDem(r.id);msg.success('DEM已删除');await load()}catch(e:any){msg.error(e.message)}}
const chooseUav=(event:Event)=>{const input=event.target as HTMLInputElement;pendingUav.value=input.files?.[0]||null;input.value='';if(pendingUav.value)uavUploadVisible.value=true}
const uploadUav=async()=>{if(!pendingUav.value||!uavForm.value.project_id)return;uavUploading.value=true;try{const meta=Object.fromEntries(Object.entries(uavForm.value).map(([k,v])=>[k,v||''])) as Record<string,string>;await api.uploadUav(pendingUav.value,meta);uavUploadVisible.value=false;pendingUav.value=null;msg.success('无人机正射影像导入成功');await load()}catch(e:any){msg.error(e.message)}finally{uavUploading.value=false}}
const openUav=async(r:UavDataset)=>{try{uavDetail.value=await api.uavDataset(r.id);uavDetailVisible.value=true}catch(e:any){msg.error(e.message)}}
const removeUav=async(r:UavDataset)=>{try{await api.removeUav(r.id);msg.success('无人机影像已删除或归档');await load()}catch(e:any){msg.error(e.message)}}
const rainValue=(v:number|null)=>v==null?'无数据':`${v.toFixed(2)} mm`
const loadRain=async()=>{if(!rainProjectId.value){rainStations.value=[];rainObservations.value=[];rainEvents.value=[];rainOverview.value=null;return}try{[rainStations.value,rainObservations.value,rainEvents.value,rainOverview.value]=await Promise.all([api.rainfallStations(rainProjectId.value),api.rainfallObservations(rainProjectId.value),api.rainfallEvents(rainProjectId.value),api.rainfallOverview(rainProjectId.value)])}catch(e:any){msg.error(e.message)}}
const openStation=(r?:RainfallStation)=>{editingStation.value=r||null;stationForm.value=r?{station_code:r.station_code,station_name:r.station_name,station_type:r.station_type,source_name:r.source_name,x:r.x,y:r.y,crs:r.crs||'',location_description:r.location_description}:{station_code:'',station_name:'',station_type:'manual_station',source_name:'',x:null,y:null,crs:'',location_description:''};stationVisible.value=true}
const saveStation=async()=>{if(!rainProjectId.value)return;try{const p={...stationForm.value,project_id:rainProjectId.value,crs:stationForm.value.crs||null};if(editingStation.value)await api.updateRainfallStation(editingStation.value.id,p);else await api.createRainfallStation(p);stationVisible.value=false;msg.success('雨量站已保存');await loadRain()}catch(e:any){msg.error(e.message)}}
const archiveStation=async(r:RainfallStation)=>{try{await api.archiveRainfallStation(r.id);msg.success('雨量站已归档');await loadRain()}catch(e:any){msg.error(e.message)}}
const saveObservation=async()=>{if(!rainProjectId.value||!observationForm.value.station_id)return;try{await api.createRainfallObservation({...observationForm.value,project_id:rainProjectId.value,source_type:'manual'});observationVisible.value=false;msg.success('观测已保存');await loadRain()}catch(e:any){msg.error(e.message)}}
const removeObservation=async(r:RainfallObservation)=>{try{await api.removeRainfallObservation(r.id);msg.success('观测已删除');await loadRain()}catch(e:any){msg.error(e.message)}}
const importRainCsv=async(event:Event)=>{const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!rainProjectId.value)return;try{rainImportResult.value=await api.importRainfallCsv(rainProjectId.value,file);rainImportVisible.value=true;await loadRain()}catch(e:any){msg.error(e.message)}}
const generateEvents=async()=>{if(!rainProjectId.value)return;rainGenerating.value=true;try{await api.generateRainfallEvents(rainProjectId.value);msg.success('已生成新版本降雨事件');await loadRain()}catch(e:any){msg.error(e.message)}finally{rainGenerating.value=false}}
const columns=[{type:'selection' as const},{title:'文件名',key:'filename',ellipsis:{tooltip:true}},{title:'尺寸',render:(r:Dataset)=>`${r.width} × ${r.height}`},{title:'波段',key:'bands'},{title:'CRS',key:'crs'},{title:'状态',render:()=>h(NTag,{type:'success',size:'small'},{default:()=> '有效'})},{title:'导入时间',render:(r:Dataset)=>formatDateTime(r.created_at)},{title:'操作',render:(r:Dataset)=>h('div',{style:'display:flex;gap:8px'},[h(NButton,{size:'small',onClick:()=>openDetail(r)},{default:()=> '详情'}),h(NPopconfirm,{onPositiveClick:()=>remove(r)},{trigger:()=>h(NButton,{size:'small',type:'error',secondary:true},{default:()=> '删除'}),default:()=> '确认删除未使用数据？'})])}];
const batchColumns=[{title:'文件名',key:'filename',ellipsis:{tooltip:true}},{title:'状态',render:(r:BatchUploadItem)=>h(NTag,{size:'small',type:r.status==='success'?'success':r.status==='duplicate'?'warning':'error'},{default:()=>({success:'上传成功',duplicate:'数据已存在',failed:'上传失败'}[r.status])})},{title:'说明',key:'message',ellipsis:{tooltip:true}}];
const demColumns=[{title:'名称',key:'name',width:190,ellipsis:{tooltip:true}},{title:'所属项目',render:(r:TerrainDataset)=>projects.value.find(x=>x.id===r.project_id)?.project_name||'通用数据',width:150},{title:'CRS',key:'crs',width:130},{title:'尺寸',render:(r:TerrainDataset)=>`${r.width} × ${r.height}`,width:110},{title:'高程范围',render:(r:TerrainDataset)=>`${r.min_elevation.toFixed(1)} ~ ${r.max_elevation.toFixed(1)} m`,width:160},{title:'有效比例',render:(r:TerrainDataset)=>`${((1-r.nodata_ratio)*100).toFixed(1)}%`,width:100},{title:'来源',render:(r:TerrainDataset)=>r.source_name||'未填写',width:120},{title:'导入时间',render:(r:TerrainDataset)=>formatDateTime(r.created_at),width:160},{title:'操作',fixed:'right' as const,width:230,render:(r:TerrainDataset)=>h('div',{style:'display:flex;gap:6px'},[h(NButton,{size:'small',onClick:()=>openDem(r)},{default:()=>'详情'}),h(NButton,{size:'small',onClick:()=>deriveDem(r)},{default:()=>'生成地形分析'}),h(NPopconfirm,{onPositiveClick:()=>removeDem(r)},{trigger:()=>h(NButton,{size:'small',type:'error',secondary:true},{default:()=>'删除'}),default:()=>'已被地形结果引用的DEM不能删除。'})])}]
const uavColumns=[{title:'影像名称',key:'name',width:190,ellipsis:{tooltip:true}},{title:'项目',key:'project_name',width:140},{title:'采集时间',render:(r:UavDataset)=>r.capture_time?formatDateTime(r.capture_time):'未填写',width:165},{title:'航飞',render:(r:UavDataset)=>r.flight_name||'未填写',width:130},{title:'CRS',key:'crs',width:130},{title:'尺寸/波段',render:(r:UavDataset)=>`${r.width} × ${r.height} · ${r.band_count}`,width:145},{title:'像素尺寸',render:(r:UavDataset)=>`${r.pixel_size_x.toFixed(3)} × ${r.pixel_size_y.toFixed(3)}`,width:150},{title:'来源',render:(r:UavDataset)=>r.source_name||'未填写',width:130},{title:'状态',render:(r:UavDataset)=>h(NTag,{type:r.status==='archived'?'default':'success'},{default:()=>r.status==='archived'?'已归档':'有效'}),width:90},{title:'操作',fixed:'right' as const,width:150,render:(r:UavDataset)=>h('div',{style:'display:flex;gap:6px'},[h(NButton,{size:'small',onClick:()=>openUav(r)},{default:()=>'详情'}),h(NPopconfirm,{onPositiveClick:()=>removeUav(r)},{trigger:()=>h(NButton,{size:'small',type:'error',secondary:true},{default:()=>'删除/归档'}),default:()=>'已有覆盖或复核引用时将归档并保留历史。'})])}]
const stationColumns=[{title:'编号',key:'station_code'},{title:'名称',key:'station_name'},{title:'类型',render:(r:RainfallStation)=>({manual_station:'人工观测点',automatic_station:'自动雨量站',external_source:'外部数据源'}[r.station_type])},{title:'坐标',render:(r:RainfallStation)=>r.x==null?'未填写':`${r.x}, ${r.y} · ${r.crs}`},{title:'来源',render:(r:RainfallStation)=>r.source_name||'未填写'},{title:'操作',render:(r:RainfallStation)=>h('div',{style:'display:flex;gap:6px'},[h(NButton,{size:'small',onClick:()=>openStation(r)},{default:()=>'编辑'}),h(NPopconfirm,{onPositiveClick:()=>archiveStation(r)},{trigger:()=>h(NButton,{size:'small',secondary:true},{default:()=>'归档'}),default:()=>'归档后保留历史观测。'})])}]
const observationColumns=[{title:'站点',key:'station_code'},{title:'观测时间',render:(r:RainfallObservation)=>formatDateTime(r.observed_at)},{title:'间隔',render:(r:RainfallObservation)=>`${r.interval_minutes} 分钟`},{title:'降雨量',render:(r:RainfallObservation)=>`${r.rainfall_mm.toFixed(2)} mm`},{title:'时段平均雨强',render:(r:RainfallObservation)=>`${r.rainfall_rate_mm_h.toFixed(2)} mm/h`},{title:'来源说明',render:(r:RainfallObservation)=>r.source_note||'未填写'},{title:'操作',render:(r:RainfallObservation)=>h(NPopconfirm,{onPositiveClick:()=>removeObservation(r)},{trigger:()=>h(NButton,{size:'small',type:'error',secondary:true},{default:()=>'删除'}),default:()=>'进入正式背景的观测不能删除。'})}]
const eventColumns=[{title:'事件',key:'event_name'},{title:'开始',render:(r:RainfallEvent)=>formatDateTime(r.start_time)},{title:'结束',render:(r:RainfallEvent)=>formatDateTime(r.end_time)},{title:'累计降雨',render:(r:RainfallEvent)=>`${r.total_rainfall_mm.toFixed(2)} mm`},{title:'峰值时段平均雨强',render:(r:RainfallEvent)=>`${r.peak_rainfall_rate_mm_h.toFixed(2)} mm/h`},{title:'站点/记录',render:(r:RainfallEvent)=>`${r.station_count} / ${r.observation_count}`},{title:'规则版本',key:'rule_version'}]
</script>
<style scoped>.rain-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) repeat(4,auto);gap:10px}.dem-form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px}.terrain-images{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0}.terrain-images img{width:100%;height:220px;object-fit:contain;background:rgba(100,145,165,.08)}.uav-preview{display:block;width:100%;max-height:520px;object-fit:contain;margin:16px 0;background:rgba(100,145,165,.08)}@media(max-width:900px){.rain-toolbar{grid-template-columns:1fr 1fr}.rain-toolbar>:first-child{grid-column:1/-1}}@media(max-width:760px){.dem-form,.terrain-images{grid-template-columns:1fr}}</style>
